import{z as i,x as d,o as e,c as n,q as t,j as A,D as a,d as s,s as o,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"进程与调度的实现","description":"","frontmatter":{"title":"进程与调度的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-process-scheduler.md","filePath":"cs/osk-process-scheduler.md","lastUpdated":1791413859000}'),c={name:"cs/osk-process-scheduler.md"};function p(h,E,C,u,m,D){const r=d("Mermaid");return e(),n("div",null,[E[2]||(E[2]=t('<h1 id="进程与调度的实现" tabindex="-1">进程与调度的实现 <a class="header-anchor" href="#进程与调度的实现" aria-label="Permalink to &quot;进程与调度的实现&quot;">​</a></h1><div class="epigraph"><p>策略挑的是下一个该跑的进程；实现兑现这个选择的，只有一次栈指针与指令指针的交换。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Arpaci-Dusseau, OSTEP 整理</footer></div><p><a href="/cs/dbk-map">上一课</a>给「数据库内核实践」收束：执行器、事务、缓冲池、日志、页、提交六个契约连成一条路径、无一处旁路；闩管形状，锁与快照管内容，日志管持久——层间越权是组装的头号事故。数据库的总装图画完了，操作系统的零件图其实也齐了：整个调度课序把「选谁运行」讲成了算法——先有<a href="/cs/scheduling-metrics">调度指标</a>定尺子，再有 EEVDF、实时与 sched_ext 各自的策略，<a href="/cs/process-addrspace-tour">进程地址空间一览</a>又把进程画成一张用户地图。两条线都停在实现之外：进程对象长什么样、切换到底切什么、运行队列怎么挂在 CPU 上，主干一律没有给出。本课是「操作系统内核实践」的第一课，从内核源码的骨架补齐这一层；后课默认你已读过这些主干课，只补实现这一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干留下的缺口不是「策略好不好」，而是装配：fork 生成的那个进程对象由谁放进哪个队列；schedule 从被调用到下一条用户指令执行，中间经过哪几步；EEVDF 的红黑树、实时位图、deadline 队列同时存在时，选路怎么定。不这么做会错在哪：把上下文切换想成「保存全部寄存器再恢复」，就会在源码里寻找一段不存在的「全量保存」——实际切换只换内核栈与最小寄存器组，其余寄存器靠调用约定在函数边界自然保留，找不到全量代码不是源码缺失，而是理解错了机制。</p><p><span class="marginnote">常见误区：初学者容易在源码里找「保存全部寄存器」的那段代码——找不到就以为自己看漏了。实际上切换只保存栈指针与少量寄存器，其余由编译器按调用约定在函数边界自然保留；没有全量保存不是源码缺失，是机制本来如此。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从对象出发读骨架。进程控制块是枢纽：标识、状态、调度信息、地址空间指针、文件表指针全挂在它上面（主干<a href="/cs/pcb-task-struct">PCB 与 task_struct</a>给过字段清单，本课只看装配）。<a href="/cs/fork">fork</a> 复制一份并把它挂上运行队列；每 CPU 一个运行队列，队列不是一条队，而是按调度类分层：stop、deadline、rt、fair、idle 各自持有自己的数据结构——公平类的红黑树按虚拟时间排序（<a href="/cs/eevdf">EEVDF</a>），rt 类用优先级数组。schedule 的选择规则是固定顺序问一遍调度类：谁先声明「我有可跑的」，就用谁的选择函数挑下一个。唤醒、时钟滴答、迁移都汇到同一个 schedule 入口，这条单一入口就是内核敢承诺一致性的原因。</p><p><span class="marginnote">术语翻译：每 CPU 运行队列是「每个收银台各排各的队」——进程不排全国一条长队，免得队首的锁被所有核争抢；调度类是队列里的「分流规则」：先问加急通道（实时）、再问预约通道（deadline）、最后按公平轮流（fair），全空才轮到 idle。</span></p>',9)),(e(),A(l,null,{default:a(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FORK%5B%22fork%EF%BC%9A%E5%A4%8D%E5%88%B6%E8%BF%9B%E7%A8%8B%E6%8E%A7%E5%88%B6%E5%9D%97%22%5D%20--%3E%20ENQ%5B%22%E6%8C%82%E4%B8%8A%E6%AF%8F%20CPU%20%E8%BF%90%E8%A1%8C%E9%98%9F%E5%88%97%22%5D%0A%20%20ENQ%20--%3E%20TICK%5B%22%E6%97%B6%E9%92%9F%E4%B8%8E%E5%94%A4%E9%86%92%E7%82%B9%E8%B0%83%E7%94%A8%20schedule%22%5D%0A%20%20TICK%20--%3E%20PICK%5B%22%E6%8C%89%E8%B0%83%E5%BA%A6%E7%B1%BB%E5%9B%BA%E5%AE%9A%E9%A1%BA%E5%BA%8F%E8%AF%A2%E9%97%AE%22%5D%0A%20%20PICK%20--%3E%20NEXT%5B%22%E9%80%89%E6%8B%A9%E5%87%BD%E6%95%B0%EF%BC%9A%E7%BA%A2%E9%BB%91%E6%A0%91%E6%9C%80%E5%B7%A6%E6%88%96%E4%BD%8D%E5%9B%BE%E6%9C%80%E9%AB%98%22%5D%0A%20%20NEXT%20--%3E%20SWMM%5B%22switch_mm%EF%BC%9A%E6%8D%A2%E9%A1%B5%E8%A1%A8%E5%9F%BA%E5%9D%80%22%5D%0A%20%20SWMM%20--%3E%20SWTO%5B%22switch_to%EF%BC%9A%E6%8D%A2%E5%86%85%E6%A0%B8%E6%A0%88%E4%B8%8E%E6%89%A7%E8%A1%8C%E6%B5%81%22%5D%0A%20%20SWTO%20--%3E%20RUN%5B%22%E4%B8%8B%E4%B8%80%E6%9D%A1%E7%94%A8%E6%88%B7%E6%8C%87%E4%BB%A4%E5%B1%9E%E4%BA%8E%E6%96%B0%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[s("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"上下文切换分两半。switch_mm 换地址空间：装入新进程的页表基址，TLB 的处理留给下一课；switch_to 换执行流：只保存并恢复栈指针与少量寄存器，并偷换返回地址。为什么这样就够：内核里所有局部状态都经由当前栈访问，编译器按调用约定把被调用者保存寄存器压在函数边界，切走时自然留在旧栈上，切回时自然从旧栈恢复。不这么做会错在哪：切换若是普通函数调用链上的一个函数，手工「全量保存」反而破坏约定——调度不是异常入口，它运行在被换下进程的内核栈里，这决定了栈指针本身就是切换的主体。",-1)),(e(),A(l,null,{default:a(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCHED%5B%22schedule%20%E5%8F%91%E9%97%AE%22%5D%20--%3E%20Q1%7B%22stop%20%E7%B1%BB%E6%9C%89%E5%8F%AF%E8%B7%91%E4%BB%BB%E5%8A%A1%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%9C%89%22%7C%20P1%5B%22%E9%80%89%E5%AE%83%2C%20%E8%AF%A2%E9%97%AE%E7%BB%93%E6%9D%9F%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%97%A0%22%7C%20Q2%7B%22deadline%20%E7%B1%BB%E6%9C%89%E5%88%B0%E6%9C%9F%E7%9A%84%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%9C%89%22%7C%20P2%5B%22%E9%80%89%E5%AE%83%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%97%A0%22%7C%20Q3%7B%22%E5%AE%9E%E6%97%B6%E7%B1%BB%E4%BD%8D%E5%9B%BE%E6%9C%89%E9%9D%9E%E7%A9%BA%E4%BC%98%E5%85%88%E7%BA%A7%3F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%9C%89%22%7C%20P3%5B%22%E9%80%89%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%9A%84%E5%AE%9E%E6%97%B6%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20Q3%20--%3E%7C%22%E6%97%A0%22%7C%20FAIR%5B%22%E5%85%AC%E5%B9%B3%E7%B1%BB%E7%BA%A2%E9%BB%91%E6%A0%91%E5%8F%96%E6%9C%80%E5%B7%A6%3B%20%E5%86%8D%E7%A9%BA%E5%88%99%20idle%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：switch_to 像换司机不换车——车（内核）继续开，只换握方向盘的手（栈指针）与看路的眼睛（指令指针）；每位司机自己的随身物品早就放在各自的座位上（各自的内核栈），回来时原样还在。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课钉骨架，不钉字段：具体结构体名随内核版本漂移，课序钉的是机制对象。负载均衡与拓扑是<a href="/cs/sched-domains">调度域与拓扑</a>的对象，组级带宽是<a href="/cs/cgroup-cpu-sched">cgroup CPU 组调度</a>的对象，实时准入与期限预算也不在此处。切换的直读成本为什么常被低估到十倍：寄存器与栈只占小头，大头是缓存工作集与 TLB 的冷却——这笔账要用下一课的页表与 TLB 结构才能算清，本课只立下「别按寄存器数估成本」这条规矩。</p><p><span class="marginnote">一次切换的直接开销（寄存器与栈）在亚微秒量级，端到端实测常到 1–5 微秒：差额在缓存与 TLB 冷却。容量规划若按寄存器数估算切换成本，结论会乐观约一个数量级。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进程控制块是装配枢纽；fork 造出它，每 CPU 运行队列按调度类分层持有它。</li><li>schedule 固定顺序询问调度类，选择函数在各自数据结构上挑选下一个。</li><li>上下文切换只有两步：换页表基址、换内核栈与执行流，其余靠调用约定。</li><li>切换成本的大头在缓存与 TLB 冷却，不在寄存器；单入口 schedule 是一致性的来源。</li><li>出处：Tanenbaum and Bos, <em>Modern Operating Systems</em>；Arpaci-Dusseau, <em>OSTEP</em>；Linux 调度器源码骨架。</li></ul>',6))])}const T=i(c,[["render",p]]);export{_ as __pageData,T as default};
